+                body: JSON.stringify({ username, password })
+            });
+
+            const data = await res.json();
+
+            const err = document.getElementById("login-error");
+            if (data.success) {
+                err.style.display = "none";
+                alert(data.message);
+                window.location.href = "/"; // redirect ไปหน้า index
